contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= amount);
        // fund c with exactly `amount` (plus test contract receives nothing extra)
        c.sendTo(address(this), amount); if (__ESBMC_reverted()) return;
        uint balBefore = address(c).balance;
        require(balBefore == amount);
        bool reverted;
        c.sendTo(address(this), amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }
        assert(!reverted && address(c).balance == 0 && address(this).balance >= balBefore);
    }
    receive() external payable {}
}

